package io.github.javacodeintel.mcp.mcp;

import io.github.javacodeintel.mcp.config.ProjectOptions;
import io.github.javacodeintel.mcp.decompile.VineflowerDecompiler;
import io.github.javacodeintel.mcp.domain.*;
import io.github.javacodeintel.mcp.project.IndexCoordinator;
import io.github.javacodeintel.mcp.query.*;
import java.io.IOException;
import java.nio.file.Path;
import java.util.*;

public final class ToolHandlers {
    public record ToolResult(Map<String,Object> data,String text,boolean error,String code){public static ToolResult ok(Map<String,Object> data,String text){return new ToolResult(data,text,false,null);}public static ToolResult error(String code,String text){return new ToolResult(Map.of("code",code,"message",text),text,true,code);}}
    public ToolResult handle(String name,Map<String,Object> args){try{return switch(name){case "index_project"->index(args);case "get_index_status"->status(args);case "search_classes"->searchClasses(args);case "get_class"->getClassInfo(args);case "get_method"->getMethod(args);case "get_field"->getField(args);case "find_subtypes"->subtypes(args);case "find_callers"->callers(args);case "decompile_class"->decompile(args);default->ToolResult.error("INVALID_ARGUMENT","Unknown tool: "+name);};}catch(IllegalArgumentException e){return ToolResult.error("INVALID_ARGUMENT",e.getMessage());}catch(IOException e){return ToolResult.error("INDEX_ERROR",e.getMessage()==null?"I/O failure":e.getMessage());}}
    private ToolResult index(Map<String,Object> a)throws IOException{Path project=project(a);ProjectOptions options=options(a);try(IndexCoordinator coordinator=IndexCoordinator.open(project,options)){IndexSummary summary=coordinator.index(project,options,bool(a,"force",false));return ToolResult.ok(Map.of("summary",summary),"Indexed "+summary.jarsIndexed()+" jars, reused "+summary.jarsReused());}}
    private ToolResult status(Map<String,Object> a)throws IOException{Path project=project(a);ProjectOptions options=options(a);try(IndexCoordinator coordinator=IndexCoordinator.open(project,options)){IndexSummary summary=coordinator.store().summary();return ToolResult.ok(Map.of("summary",summary),"Index contains "+summary.classes()+" classes");}}
    private ToolResult searchClasses(Map<String,Object> a)throws IOException{Path project=project(a);String query=required(a,"query");try(IndexCoordinator coordinator=IndexCoordinator.open(project,options(a))){PageResult<ClassInfo> page=new ClassQueryService(coordinator.store()).search(query,page(a));return ToolResult.ok(Map.of("items",page.items(),"page",page),"Found "+page.total()+" classes");}}
    private ToolResult getClassInfo(Map<String,Object> a)throws IOException{Path project=project(a);String name=required(a,"className");try(IndexCoordinator coordinator=IndexCoordinator.open(project,options(a))){Optional<ClassInfo> found=new ClassQueryService(coordinator.store()).get(name);if(found.isEmpty())return ToolResult.error("NOT_FOUND","Class not found: "+name);Map<String,Object> data=new LinkedHashMap<>();data.put("class",found.get());if(bool(a,"includeMembers",true)){data.put("fields",coordinator.store().findFields(name,null));data.put("methods",coordinator.store().findMethods(name,null,null));}return ToolResult.ok(data,found.get().name());}}
    private ToolResult getMethod(Map<String,Object> a)throws IOException{Path project=project(a);String owner=required(a,"owner"),method=required(a,"method");String descriptor=optional(a,"descriptor");try(IndexCoordinator coordinator=IndexCoordinator.open(project,options(a))){PageResult<MethodInfo> page=new MethodQueryService(coordinator.store()).find(owner,method,descriptor,page(a));return ToolResult.ok(Map.of("items",page.items(),"page",page),"Found "+page.total()+" methods");}}
    private ToolResult getField(Map<String,Object> a)throws IOException{Path project=project(a);String owner=required(a,"owner");String field=optional(a,"fieldName");try(IndexCoordinator coordinator=IndexCoordinator.open(project,options(a))){PageResult<FieldResult> page=new FieldQueryService(coordinator.store()).find(owner,field,bool(a,"includeAccessors",true),page(a));return ToolResult.ok(Map.of("items",page.items(),"page",page),"Found "+page.total()+" fields");}}
    private ToolResult subtypes(Map<String,Object> a)throws IOException{Path project=project(a);String type=required(a,"typeName");try(IndexCoordinator coordinator=IndexCoordinator.open(project,options(a))){PageResult<ClassInfo> page=new RelationQueryService(coordinator.store()).subtypes(type,bool(a,"recursive",true),bool(a,"includeInterfaces",true),page(a));return ToolResult.ok(Map.of("type",type,"items",page.items(),"page",page),"Found "+page.total()+" subtypes");}}
    private ToolResult callers(Map<String,Object> a)throws IOException{Path project=project(a);String owner=required(a,"owner"),method=required(a,"method");String descriptor=optional(a,"descriptor");if(descriptor==null)throw new IllegalArgumentException("descriptor is required for find_callers");try(IndexCoordinator coordinator=IndexCoordinator.open(project,options(a))){PageResult<CallEdge> page=new RelationQueryService(coordinator.store()).callers(owner,method,descriptor,"polymorphic".equals(optional(a,"matchMode")),page(a));return ToolResult.ok(Map.of("items",page.items(),"page",page),"Found "+page.total()+" callers");}}
    private ToolResult decompile(Map<String,Object> a)throws IOException{Path project=project(a);String name=required(a,"className");try(IndexCoordinator coordinator=IndexCoordinator.open(project,options(a))){ClassInfo indexed=coordinator.store().findClass(name).orElse(null);if(indexed==null)return ToolResult.error("NOT_FOUND","Class not found: "+name);VineflowerDecompiler decompiler=new VineflowerDecompiler(coordinator.store(),io.github.javacodeintel.mcp.project.ProjectCacheLayout.forProject(project).decompiled());DecompiledSource source=decompiler.decompile(project,indexed.jar(),name,intValue(a,"targetJavaRelease",options(a).targetJavaRelease()),bool(a,"force",false));return ToolResult.ok(Map.of("className",source.className(),"source",source.source(),"cached",source.cached(),"sourcePath",String.valueOf(source.sourcePath()),"decompiler",source.decompilerVersion()),"Decompiled "+name);}}
    private static PageRequest page(Map<String,Object> a){return new PageRequest(intValue(a,"limit",PageRequest.DEFAULT_LIMIT),intValue(a,"offset",0));}
    private static ProjectOptions options(Map<String,Object> a){int release=intValue(a,"targetJavaRelease",8);boolean enforce=bool(a,"enforceTargetRelease",false);ChangeDetectionMode mode;try{mode=ChangeDetectionMode.valueOf(String.valueOf(a.getOrDefault("changeDetection","NONE")).toUpperCase(Locale.ROOT));}catch(Exception e){throw new IllegalArgumentException("Invalid changeDetection");}return new ProjectOptions(release,enforce,mode,bool(a,"includeTestDependencies",false));}
    private static Path project(Map<String,Object> a){return Path.of(required(a,"projectPath"));}
    private static String required(Map<String,Object> a,String key){String value=optional(a,key);if(value==null||value.isBlank())throw new IllegalArgumentException(key+" is required");return value;}
    private static String optional(Map<String,Object> a,String key){Object value=a.get(key);return value==null?null:String.valueOf(value);}
    private static boolean bool(Map<String,Object> a,String key,boolean fallback){Object value=a.get(key);return value==null?fallback:Boolean.parseBoolean(String.valueOf(value));}
    private static int intValue(Map<String,Object> a,String key,int fallback){Object value=a.get(key);if(value==null)return fallback;try{return Integer.parseInt(String.valueOf(value));}catch(NumberFormatException e){throw new IllegalArgumentException(key+" must be an integer");}}
}
